CREATE DATABASE IF NOT EXISTS qolak CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE qolak;
CREATE TABLE roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,slug VARCHAR(60) UNIQUE NOT NULL);
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,role_id BIGINT UNSIGNED NOT NULL,first_name VARCHAR(100),last_name VARCHAR(100),national_code VARCHAR(20),mobile VARCHAR(20) UNIQUE,username VARCHAR(80) UNIQUE,password VARCHAR(255) NOT NULL,address TEXT,card_number VARCHAR(30),account_number VARCHAR(40),iban VARCHAR(40),status ENUM('active','suspended','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL,FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE funds(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,code VARCHAR(60) UNIQUE NOT NULL,description TEXT,monthly_amount DECIMAL(18,2) NOT NULL,member_count INT NOT NULL,duration_months INT NOT NULL,start_date DATE,end_date DATE,status ENUM('active','closed','archived') DEFAULT 'active',rules TEXT,exclude_debtors_from_draw TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE fund_members(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fund_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,joined_at DATE,status ENUM('active','inactive','suspended') DEFAULT 'active',receive_priority INT,notes TEXT,UNIQUE(fund_id,user_id),FOREIGN KEY(fund_id) REFERENCES funds(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE installments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fund_id BIGINT UNSIGNED,user_id BIGINT UNSIGNED,amount DECIMAL(18,2),due_date DATE,status ENUM('paid','unpaid','partial','overdue') DEFAULT 'unpaid',paid_at DATETIME NULL,transaction_no VARCHAR(100),description TEXT,FOREIGN KEY(fund_id) REFERENCES funds(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,installment_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED,fund_id BIGINT UNSIGNED,amount DECIMAL(18,2),paid_at DATETIME,method VARCHAR(50),receipt_path VARCHAR(255),status ENUM('pending','approved','rejected') DEFAULT 'pending',description TEXT,FOREIGN KEY(installment_id) REFERENCES installments(id));
CREATE TABLE transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fund_id BIGINT UNSIGNED,user_id BIGINT UNSIGNED NULL,type ENUM('deposit','withdrawal','winner_payout','fee','expense') NOT NULL,amount DECIMAL(18,2) NOT NULL,status ENUM('draft','approved','rejected') DEFAULT 'draft',description TEXT,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE draws(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fund_id BIGINT UNSIGNED NOT NULL,draw_uid VARCHAR(80) UNIQUE NOT NULL,seed VARCHAR(128) NOT NULL,participants_snapshot JSON NOT NULL,winner_user_id BIGINT UNSIGNED NOT NULL,executed_by BIGINT UNSIGNED NOT NULL,executed_at DATETIME NOT NULL,FOREIGN KEY(fund_id) REFERENCES funds(id));
CREATE TABLE draw_participants(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,draw_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,eligible TINYINT(1) DEFAULT 1,FOREIGN KEY(draw_id) REFERENCES draws(id));
CREATE TABLE winners(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fund_id BIGINT UNSIGNED NOT NULL,draw_id BIGINT UNSIGNED NOT NULL,winner_user_id BIGINT UNSIGNED NOT NULL,won_at DATETIME NOT NULL,FOREIGN KEY(draw_id) REFERENCES draws(id));
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,title VARCHAR(160),body TEXT,type VARCHAR(60),read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE documents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,payment_id BIGINT UNSIGNED NULL,path VARCHAR(255),mime VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,entity VARCHAR(80),entity_id BIGINT UNSIGNED NULL,ip VARCHAR(64),user_agent VARCHAR(255),metadata JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`key` VARCHAR(100) UNIQUE NOT NULL,`value` TEXT);
CREATE TABLE ledger_entries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_type VARCHAR(80) NOT NULL,reference_id BIGINT UNSIGNED NOT NULL,description TEXT,total_debit DECIMAL(18,2) NOT NULL,total_credit DECIMAL(18,2) NOT NULL,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CHECK(total_debit=total_credit));
CREATE TABLE ledger_lines(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ledger_entry_id BIGINT UNSIGNED NOT NULL,account_code VARCHAR(40) NOT NULL,account_title VARCHAR(160) NOT NULL,debit DECIMAL(18,2) DEFAULT 0,credit DECIMAL(18,2) DEFAULT 0,party_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(ledger_entry_id) REFERENCES ledger_entries(id));
